INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(10001, '1 Chronicles 8:29', '1 Chronicles', 8, 29, '&nbsp;يعى‌ايل د جبعون ښار جوړ کړو او هلته اوسېدو. د هغۀ د ښځې نوم معکه وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10002, '1 Chronicles 8:30', '1 Chronicles', 8, 30, '&nbsp;او د هغۀ مشر زوئ عبدون وو. د هغۀ نور زامن صور، قيس، بعل، نير، ندب،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10003, '1 Chronicles 8:31', '1 Chronicles', 8, 31, '&nbsp;جدور، اخيو، زکر،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10004, '1 Chronicles 8:32', '1 Chronicles', 8, 32, '&nbsp;او مِقلوت چې د سِمعا پلار وو. د هغوئ اولاد په يروشلم کښې د خپلې قبيلې د نورو کورَنو سره نزدې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10005, '1 Chronicles 8:33', '1 Chronicles', 8, 33, '&nbsp;نير د قيس پلار وو او قيس د ساؤل بادشاه پلار وو. د ساؤل څلور زامن وو: يونتن، مُلکى‌شوَع، ابينداب او اشبعل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10006, '1 Chronicles 8:34', '1 Chronicles', 8, 34, '&nbsp;يونتن د مريب بعل پلار وو، چې هغه د ميکاه پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10007, '1 Chronicles 8:35', '1 Chronicles', 8, 35, '&nbsp;د ميکاه څلور زامن وُو: فيتون، مُلک، تاريع او احاز.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10008, '1 Chronicles 8:36', '1 Chronicles', 8, 36, '&nbsp;احاز د يهوعده پلار وو، چې هغه د درېو زامنو پلار وو: علمت، عزماوت او زِمرى. زِمرى د موضا پلار وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10009, '1 Chronicles 8:37', '1 Chronicles', 8, 37, '&nbsp;موضا د بِنعه پلار وو، بِنعه د رفعه، رفعه د اِلعاسه، اِلعاسه د اصيل پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10010, '1 Chronicles 8:38', '1 Chronicles', 8, 38, '&nbsp;د اصيل شپږ زامن وُو: عزريقام، بوکرو، اِسمٰعيل، سعرياه، عبدياه او حنان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10011, '1 Chronicles 8:39', '1 Chronicles', 8, 39, '&nbsp;د اصيل د ورور عيشق درې زامن وُو: اولام، يعوس او اليفلط.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10012, '1 Chronicles 8:40', '1 Chronicles', 8, 40, '&nbsp;د اولام زامن تکړه فوجيان او د غشو ويشتونکى وُو. د هغۀ ټول زامن او نمسى يو نيم سل وُو. دا ټول کسان د بنيامين اولاد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10013, '1 Chronicles 9:1', '1 Chronicles', 9, 1, '&nbsp;د ټولو بنى اِسرائيلو نسب‌نامه ليکلے شوې وه او دا معلومات د بنى اِسرائيلو د بادشاهانو د تاريخ په کِتاب کښې ليکلے شوى دى. د يهوداه خلق د خپلې نافرمانۍ په وجه بابل ته ويستلے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10014, '1 Chronicles 9:2', '1 Chronicles', 9, 2, '&nbsp;وړومبى کسان چې په خپلو پخوانو ښارونو کښې جائيدادونو ته راواپس شول نو په هغې کښې اِمامان، ليويان، د مالِک خُدائ د کور خِدمت کوونکى او نور بنى اِسرائيليان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10015, '1 Chronicles 9:3', '1 Chronicles', 9, 3, '&nbsp;د يهوداه، بنيامين، اِفرائيم او منسى قبيلو خلق يروشلم ته د اوسېدو دپاره لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10016, '1 Chronicles 9:9', '1 Chronicles', 9, 9, '&nbsp;د دې قبيلې نهۀ سوه شپږ پنځوس خاندان لاړل او هلته اوسېدل. د دې ليکلے شوو نومونو ټول سړى د کورَنو مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10017, '1 Chronicles 9:13', '1 Chronicles', 9, 13, '&nbsp;کوم اِمامان چې د ډلو مشران وُو هغه ټول يو زر اووۀ سوه او شپېتۀ وُو. هغوئ د خُدائ پاک د کور د خِدمت د کار دپاره ښۀ تکړه سړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10018, '1 Chronicles 9:17', '1 Chronicles', 9, 17, '&nbsp;د مالِک خُدائ د کور څوکيداران په يروشلم کښې اوسېدل: سلوم، عقوب، طلمون او اخيمان. سلوم د هغوئ مشر وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10019, '1 Chronicles 9:18', '1 Chronicles', 9, 18, '&nbsp;د دې نه مخکښې د هغو ډلو کسان د نمرخاتۀ طرف د بادشاه د دروازې سره ولاړ وُو. هغوئ به د ليويانو د خېمو په دروازو باندې څوکيدارى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10020, '1 Chronicles 9:19', '1 Chronicles', 9, 19, '&nbsp;د قورې زوئ او د ابى‌آسف نمسے سلوم، سره د خپلو خلقو چې د قورح ډله وه د مالِک خُدائ د حضور د خېمې د ننوتلو ځائ حِفاظت ذمه وار وُو، لکه څنګه چې مخکښې د هغوئ پلار نيکۀ د مالِک خُدائ د اوسېدو د ځائ د حِفاظت ذمه وار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10021, '1 Chronicles 9:20', '1 Chronicles', 9, 20, '&nbsp;د اِلى‌عزر زوئ فينحاس، په يو وخت کښې د هغوئ مشرى کړې وه او مالِک خُدائ د هغۀ مل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10022, '1 Chronicles 9:21', '1 Chronicles', 9, 21, '&nbsp;د مسلمياه زوئ زکرياه هم د مالِک خُدائ د حضور د خېمې د ننوتلو د ځائ څوکيدار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10023, '1 Chronicles 9:22', '1 Chronicles', 9, 22, '&nbsp;ټول دوه سوه او دولس سړى د دروازو دپاره څوکيداران خوښ کړے شوى وُو. د هغوئ نومونه د هغه کلو په مطابق ليکلے شوى وُو چې چرته هغوئ اوسېدل. داؤد او سموئيل پېغمبر د هغوئ پلار نيکۀ په دې اهم کار باندې مقرر کړى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10024, '1 Chronicles 9:23', '1 Chronicles', 9, 23, '&nbsp;هغوئ او د هغوئ اولاد د مالِک خُدائ د خېمې د دروازو د حِفاظت ذمه وار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10025, '1 Chronicles 9:24', '1 Chronicles', 9, 24, '&nbsp;په هر طرف باندې يوه يوه دروازه وه، شمالى، جنوبى، نمرخاتۀ او نمرپرېواتۀ ته او د هرې يوې دروازې يو يو مشر څوکيدار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10026, '1 Chronicles 9:25', '1 Chronicles', 9, 25, '&nbsp;د هغوئ هغه خپلوان کوم چې په کلو کښې اوسېدل نو هغوئ به وخت په وخت راتلل او د هغوئ سره به يې اووۀ ورځې خِدمت کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10027, '1 Chronicles 9:26', '1 Chronicles', 9, 26, '&nbsp;هغه څلور مشران څوکيداران ليويان وُو چې هغوئ له پوره ذمه وارى ورکړے شوې وه. هغوئ د مالِک خُدائ د کور د کوټو او د هغه قيمتى سامان هم خيال ساتلو چې کوم هلته کېښودے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10028, '1 Chronicles 9:27', '1 Chronicles', 9, 27, '&nbsp;هغوئ د مالِک خُدائ کور سره نزدې دېره وُو، ځکه چې د هغوئ کار د دې حِفاظت او په هر سحر کښې د دروازو کولاول وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10029, '1 Chronicles 9:28', '1 Chronicles', 9, 28, '&nbsp;څۀ ليويان د عبادت د سامان ذمه وار وُو. چې کله به دا وړلے يا واپس راوړلے شو نو هغوئ به دا شمېرلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10030, '1 Chronicles 9:29', '1 Chronicles', 9, 29, '&nbsp;نور د مقدس ځائ د سامان، د اوړو، د ميو، د زيتُونو تېلو، خوشبويۍ او مصالحو ذمه وار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10031, '1 Chronicles 9:30', '1 Chronicles', 9, 30, '&nbsp;خو د مصالحو د ګډولو ذمه وارى د اِمامانو وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10032, '1 Chronicles 9:31', '1 Chronicles', 9, 31, '&nbsp;د قورح د قبيلې د ليوى قبيلې د سلوم مشر زوئ چې نوم يې متتياه وو، هغه د هغه روټۍ پخولو ذمه وار وو چې په نذرانو کښې استعمالېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10033, '1 Chronicles 9:32', '1 Chronicles', 9, 32, '&nbsp;د قُهات د قبيلې څۀ کسان د هر سبت په ورځ د مالِک خُدائ کور دپاره د مقدسې روټۍ تيارولو ذمه وار وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10034, '1 Chronicles 9:33', '1 Chronicles', 9, 33, '&nbsp;د ليويانو څۀ خاندان د مالِک خُدائ د کور د سندرو ذمه وارې وې. د دې کورَنو مشران د مالِک خُدائ د کور په يو څو کوټو کښې اوسېدل او د نورو کارونو کولو نه آزاد وُو، ځکه چې هغوئ به شپه او ورځ کار کولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10035, '1 Chronicles 9:34', '1 Chronicles', 9, 34, '&nbsp;دا ټول کسان د هغوئ د پلار نيکۀ د نسب‌نامې په مطابق د ليويانو د خاندان مشران وُو. هغوئ د يروشلم د اوسېدونکو خلقو مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10036, '1 Chronicles 9:35', '1 Chronicles', 9, 35, '&nbsp;يعى‌ايل د جبعون ښار جوړ کړو او هلته دېره شو. د هغۀ د ښځې نوم معکه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10037, '1 Chronicles 9:36', '1 Chronicles', 9, 36, '&nbsp;د هغۀ مشر زوئ عبدون وو او د هغۀ نور زامن دا وُو: صور، قيس، بعل، نير، ندب،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10038, '1 Chronicles 9:37', '1 Chronicles', 9, 37, '&nbsp;جدور، اخيو، زکرياه او مِقلوت', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10039, '1 Chronicles 9:38', '1 Chronicles', 9, 38, '&nbsp;چې د سِمعام پلار وو. د هغوئ اولاد د خپلې قبيلې د نورو کورَنو سره نزدې په يروشلم کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10040, '1 Chronicles 9:39', '1 Chronicles', 9, 39, '&nbsp;نير د قيس پلار وو او قيس د ساؤل پلار وو. د ساؤل څلور زامن وُو: يونتن، مُلکى‌شوَع، ابينداب او اشبعل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10041, '1 Chronicles 9:40', '1 Chronicles', 9, 40, '&nbsp;يونتن د مريب بعل پلار وو، چې هغه د ميکاه پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10042, '1 Chronicles 9:41', '1 Chronicles', 9, 41, '&nbsp;د ميکاه څلور زامن وُو: فيتون، مُلک، تاريع او احاز.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10043, '1 Chronicles 9:42', '1 Chronicles', 9, 42, '&nbsp;احاز د يعراه پلار وو، چې هغه د درېو زامنو پلار وو: علمت، عزماوت او زِمرى. زِمرى د موضا پلار وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10044, '1 Chronicles 9:43', '1 Chronicles', 9, 43, '&nbsp;موضا د بِنعه پلار وو، بِنعه د رفاياه، رفاياه د اِلعاسه او اِلعاسه د اصيل پلار وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10045, '1 Chronicles 9:44', '1 Chronicles', 9, 44, '&nbsp;د اصيل شپږ زامن وُو: عزريقام، بوکرو، اِسمٰعيل، سعرياه، عبدياه او حنان.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10046, '1 Chronicles 10:1', '1 Chronicles', 10, 1, '&nbsp;فلستيانو د بنى اِسرائيلو خِلاف د جِلبوعه په غر باندې يو جنګ وکړو. هلته ډېر بنى اِسرائيليان ووژلے شول او د هغوئ نور پاتې کسان سره د ساؤل بادشاه او د هغۀ د زامنو وتښتېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10047, '1 Chronicles 10:2', '1 Chronicles', 10, 2, '&nbsp;خو فلستيان ساؤل او د هغۀ زامنو ته ورنزدې شول او د ساؤل درې زامن يونتن، ابينداب او مُلکى‌شوَع يې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10048, '1 Chronicles 10:3', '1 Chronicles', 10, 3, '&nbsp;د ساؤل نه ګېرچاپېره سخت جنګ وو او هغه په کښې د دشمن په غشو باندې ولګېدو او سخت زخمى شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10049, '1 Chronicles 10:4', '1 Chronicles', 10, 4, '&nbsp;نو هغه زلمى ته يې ووئيل چې کوم د هغۀ وسله وړله، ”خپله تُوره راوباسه او ما پرې ووهه، ګنې هغه ناسنته کسان به راشى او زما بې‌عزتى به کوى.“ خو زلمے يرېدو او داسې يې نۀ کول، نو ساؤل خپله تُوره واخسته او په هغې باندې يې ځان وروغورزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10050, '1 Chronicles 10:5', '1 Chronicles', 10, 5, '&nbsp;کله چې هغه زلمى وليدل چې ساؤل مړ شو، نو هغۀ هم خپل ځان په خپله تُوره وروغورزولو او مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10051, '1 Chronicles 10:6', '1 Chronicles', 10, 6, '&nbsp;نو ساؤل او د هغۀ درې واړه زامن په يو ځائ مړۀ شول او د هغۀ د اولاد هيچا هم بادشاهى ونۀ کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10052, '1 Chronicles 10:7', '1 Chronicles', 10, 7, '&nbsp;چې د يزرعيل په وادۍ کښې چې کوم بنى اِسرائيليان وُو نو چې هغوئ خبر شول چې لښکر تښتېدلے دے او ساؤل او د هغۀ زامن مړۀ شوى دى، نو هغوئ خپل ښارونه پرېښودل او منډه يې کړه. او بيا فلستيان راغلل او ښارونه يې قبضه کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10053, '1 Chronicles 10:8', '1 Chronicles', 10, 8, '&nbsp;په ورپسې ورځ، فلستيان د مړو لوټ کولو له لاړل او هغوئ د ساؤل او د هغۀ د زامنو لاشونه وموندل چې د جِلبوعه په غرۀ باندې پراتۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10054, '1 Chronicles 10:9', '1 Chronicles', 10, 9, '&nbsp;هغوئ د ساؤل سر پرې کړو، د هغۀ نه يې زغره کولاو کړه او د هغوئ سره يې ټولو فلستيانو ته پېغام وړُونکى ولېږل چې خپلو معبودانو او خپلو خلقو ته دا زېرے واوروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10055, '1 Chronicles 10:10', '1 Chronicles', 10, 10, '&nbsp;هغوئ د هغۀ وسله په خپله يوه عبادتخانه کښې کېښوده او د هغۀ سر يې د خپل خُدائ دجون په عبادتخانه کښې راځوړند کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10056, '1 Chronicles 10:11', '1 Chronicles', 10, 11, '&nbsp;کله چې د يبيس خلقو په جِلعاد کښې دا واورېدل چې فلستيانو د ساؤل سره څۀ کړى وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10057, '1 Chronicles 10:12', '1 Chronicles', 10, 12, '&nbsp;نو د هغوئ ټول تکړه سړى لاړل او د ساؤل او د هغۀ د زامنو لاشونه يې واخستل او يبيس ته يې يوړل. هلته هغوئ دا د څېړۍ د ونې لاندې ښخ کړل او اووۀ ورځې يې روژه ونيوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10058, '1 Chronicles 10:13', '1 Chronicles', 10, 13, '&nbsp;ساؤل ځکه مړ شو چې د مالِک خُدائ سره يې خيانت وکړو او د مالِک خُدائ د حُکمونو نافرمانى يې وکړه. هغۀ د کوډګرې ښځې په ذريعه د مړو د روحونو سره مشورې هم کولې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10059, '1 Chronicles 10:14', '1 Chronicles', 10, 14, '&nbsp;په کار خو دا وُو چې د مالِک خُدائ نه يې مشوره اخستې وے. نو مالِک خُدائ هغه ووژلو او د بادشاهۍ اختيار يې د يَسى زوئ داؤد له ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10060, '1 Chronicles 11:1', '1 Chronicles', 11, 1, '&nbsp;بيا ټول بنى اِسرائيليان په حبرون کښې داؤد له لاړل او ورته يې ووئيل، ”مونږ ستا خپله وينه يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10061, '1 Chronicles 11:2', '1 Chronicles', 11, 2, '&nbsp;په تېره زمانه کښې، کله چې لا ساؤل زمونږ بادشاه وو، نو تۀ هغه څوک وې چې په جنګ کښې دې د بنى اِسرائيلو مشرى کوله او مالِک خُدائ ستا خُدائ پاک تا سره دا لوظ وکړو چې تۀ به د هغۀ د خلقو بنى اِسرائيلو حکمران يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10062, '1 Chronicles 11:3', '1 Chronicles', 11, 3, '&nbsp;نو د بنى اِسرائيلو ټول مشران په حبرون کښې داؤد له راغلل. هغۀ د مالِک خُدائ په مخکښې د هغوئ سره يو لوظ وکړو. هغوئ د مقررولو دپاره په هغۀ باندې تېل واچول او هغه د بنى اِسرائيلو بادشاه شو، هم هغه شان چې څنګه مالِک خُدائ د سموئيل په ذريعه وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10063, '1 Chronicles 11:4', '1 Chronicles', 11, 4, '&nbsp;داؤد بادشاه او ټول بنى اِسرائيليان لاړل او د يروشلم په ښار يې حمله وکړه. په هغه وخت کښې يروشلم د يبوس په نوم يادېدو او د هغۀ مُلک اصلى اوسېدونکى يعنې يبوسيان تر هغه وخته پورې هلته اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10064, '1 Chronicles 11:5', '1 Chronicles', 11, 5, '&nbsp;يبوسيانو داؤد ته ووئيل، ”تۀ به هيڅکله ښار ته ورننه نۀ وځې.“ خو داؤد د هغوئ د صيون قلعه ونيوله او دا ځائ د داؤد په ښار مشهور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10065, '1 Chronicles 11:6', '1 Chronicles', 11, 6, '&nbsp;داؤد وفرمائيل، ”کوم يو سړے چې اول په يبوسيانو حمله وکړى نو هغه به د لښکر مشر وى.“ يوآب چې د هغۀ مور ضروياه وه، هغۀ اول حمله وکړه او هغه د لښکر مشر شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10066, '1 Chronicles 11:7', '1 Chronicles', 11, 7, '&nbsp;داؤد په قلعه کښې د اوسېدو دپاره لاړو نو په دې وجه دا د داؤد ښار بللے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10067, '1 Chronicles 11:8', '1 Chronicles', 11, 8, '&nbsp;هغۀ ښار جوړ کړو، د هغه ځائ نه يې شروع وکړه چرته چې بره ختلى پټى وُو او د ګېرچاپېره علاقې پورې يې خور کړو او يوآب باقى ښار بيا جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10068, '1 Chronicles 11:9', '1 Chronicles', 11, 9, '&nbsp;داؤد نور هم تکړه کېدو، ځکه چې ربُ الافواج د هغۀ مل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10069, '1 Chronicles 11:10', '1 Chronicles', 11, 10, '&nbsp;د داؤد د تکړه فوجيانو مشران دا دى. ټولو بنى اِسرائيلو په شريکه دا فېصله وکړه چې داؤد خپل بادشاه جوړ کړى لکه څنګه چې مالِک خُدائ وعده کړې وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10070, '1 Chronicles 11:11', '1 Chronicles', 11, 11, '&nbsp;وړومبے د حکمون د قبيلې يسوبعام وو چې د هغه ”درېو آفسرانو“ مشر وو. هغۀ د خپلې نېزې سره د درې سوو سړو خِلاف جنګ وکړو او هغه ټول يې په يو جنګ کښې ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10071, '1 Chronicles 11:12', '1 Chronicles', 11, 12, '&nbsp;ورپسې د هغه درېو مشهورو کسانو نه د دودو زوئ اِلى‌عزر، چې د اخوحى د قبيلې وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10072, '1 Chronicles 11:13', '1 Chronicles', 11, 13, '&nbsp;هغه د داؤد په ملګرتيا کښې د فسدميم په جنګ کښې د فلستيانو خِلاف وجنګېدو. کله چې بنى اِسرائيلو د فلستيانو نه تښتېدل شروع کړل نو هغه د اوربشو په يو پټى کښې وو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10073, '1 Chronicles 11:14', '1 Chronicles', 11, 14, '&nbsp;خو بيا هغه او د هغۀ سړى د پټى په مينځ کښې کلک ودرېدل او فلستيانو له يې شکست ورکړو. مالِک خُدائ هغۀ له يوه لويه فتح ورکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10074, '1 Chronicles 11:15', '1 Chronicles', 11, 15, '&nbsp;يوه ورځ د مشرانو فوجيانو د دېرشو نه درې کسان يو ګټ له لاړل چرته چې داؤد د عدولام غار سره نزدې ايسار وو، چې په دې دوران کښې د فلستيانو يوې فوجى قبيلې د رفائيم په وادۍ کښې خېمې لګولې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10075, '1 Chronicles 11:16', '1 Chronicles', 11, 16, '&nbsp;په هغه وخت کښې داؤد په يوه پخه مورچه کښې وو او د فلستيانو يوې قبيلې بيت‌لحم قبضه کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10076, '1 Chronicles 11:17', '1 Chronicles', 11, 17, '&nbsp;د داؤد اوبو ته سخت زړۀ وشو او وې فرمائيل، ”کاش چې څوک ما له د بيت‌لحم دروازې سره نزدې کوهى نه لږې اوبۀ راوړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10077, '1 Chronicles 11:18', '1 Chronicles', 11, 18, '&nbsp;نو هغه درېو مشهورو فوجيانو د فلستيانو په فوجى صفونو کښې لار جوړه کړه، د کوهى نه يې لږې اوبۀ راوويستلې او داؤد له يې راوړې. خو هغۀ دا ونۀ څښلے او د څښلو په ځائ يې مالِک خُدائ ته د نذرانې په توګه توئ کړې', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10078, '1 Chronicles 11:19', '1 Chronicles', 11, 19, '&nbsp;او وې فرمائيل، ”دا زۀ هيڅکله نۀ شم څښلے. دا به د دې سړو د وينې څښلو په شان وى چا چې خپل ژوند په خطره کښې واچولو.“ نو هغۀ د دې څښلو نه اِنکار وکړو. دا د هغه درېو تکړه فوجيانو د بهادرۍ کارنامې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10079, '1 Chronicles 11:20', '1 Chronicles', 11, 20, '&nbsp;د يوآب ورور ابيشے د هغه درېو مشهورو کسانو مشر وو. هغۀ د خپلې نېزې سره د درې سوو سړو خِلاف جنګ وکړو او هغوئ يې ووژل او د هغه درېو په شان مشهور شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10080, '1 Chronicles 11:21', '1 Chronicles', 11, 21, '&nbsp;هغه د هغه درېو نه زيات مشهور وو او د هغوئ مشر شو، خو هغه په هغه درېو کښې شامل نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10081, '1 Chronicles 11:22', '1 Chronicles', 11, 22, '&nbsp;د قبضئيل د يهويدع زوئ بناياه يو تکړه فوجى وو، هغۀ ډېرې د بهادرۍ کارنامې وکړې، چې په دې کښې د دوو تکړه موآبيانو جنګيالو وژل هم شامل وُو. يو بل ځل چې واوره ورېدله نو هغه لاندې يوې کندې ته لاړو او يو زمرے يې ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10082, '1 Chronicles 11:23', '1 Chronicles', 11, 23, '&nbsp;هغۀ يو مِصرے هم ووژلو، يو لوئ سړے چې تقريباً دوه نيم ګزه لوړ وو، د هغۀ نېزه د کوټې د تير هومره لويه وه. بناياه په هغۀ باندې د امسا سره حمله وکړه، د مِصرى د لاس نه يې نېزه واخستله او په هغې باندې يې ووژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10083, '1 Chronicles 11:24', '1 Chronicles', 11, 24, '&nbsp;دا د بناياه د بهادرۍ کارنامې وې چې هغه د هغه درېو په شان مشهور وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10084, '1 Chronicles 11:25', '1 Chronicles', 11, 25, '&nbsp;هغه د هغه دېرشو نه زيات مشهور وو، خو په هغه درېو کښې شامل نۀ وو. داؤد هغه د خپلو ذاتى محافظانو مشر جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10085, '1 Chronicles 12:1', '1 Chronicles', 12, 1, '&nbsp;دا هغه سړى دى چې په صِقلاج کښې د داؤد سره په هغه وخت ملګرى شول چې هغه د قيس زوئ ساؤل نه پټېدو. هغوئ د هغه جنګيالو نه وُو چا چې د داؤد په حق کښې جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10086, '1 Chronicles 12:2', '1 Chronicles', 12, 2, '&nbsp;دا ټول تکړه لينده چلوونکى وُو، هغوئ په ښى او ګس لاس دواړو باندې غشى او د ليندې کاڼى ويشتلے شول. هغوئ د بنيامين د قبيلې نه د ساؤل خپلوان وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10087, '1 Chronicles 12:8', '1 Chronicles', 12, 8, '&nbsp;کله چې داؤد د صحرا په قلعه کښې وو نو د جاد د قبيلې نه ځينې تکړه او تجربه‌کار فوجيان د هغۀ سره ملګرى شولو. هغوئ په ډالونو او نېزو کښې ماهِران وُو، د زمرو په شان تکړه او په غرونو کښې د هوسۍ په شان تېزې منډې يې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10088, '1 Chronicles 12:14', '1 Chronicles', 12, 14, '&nbsp;د جاد قبيلې جنګيالى فوجى مشران وُو. د هغوئ د ټولو نه کمزورو جنګيالو د سلو فوجيانو سره جنګ کولے شو او تکړه جنګيالو د زرو خِلاف جنګ کولے شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10089, '1 Chronicles 12:15', '1 Chronicles', 12, 15, '&nbsp;د يو کال په وړومبۍ مياشت کښې، په هغه وخت کښې چې د اُردن په سيند کښې اوبۀ د غاړو نه اوړېدلې، نو هغوئ د سيند نه پورې وتل، هغه خلق يې خوارۀ وارۀ کړل کوم چې د سيند نمرخاتۀ او نمرپرېواتۀ دواړو طرفونو ته په وادۍ کښې اوسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10090, '1 Chronicles 12:16', '1 Chronicles', 12, 16, '&nbsp;يو ځل د بنيامين او يهوداه د قبيلو د سړو يوه ډله هغه قلعې ته لاړه چرته چې داؤد وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10091, '1 Chronicles 12:17', '1 Chronicles', 12, 17, '&nbsp;داؤد مِلاوېدو له ورَغلو او ورته يې وفرمائيل، ”کۀ تاسو د دوستانو په شان دلته زما مدد له راغلى يئ، نو په خېر راغلئ. زمونږ سره ملګرى شئ. خو کۀ ستاسو اراده دا وى چې دوکه مې کړئ او دشمن ته مې حواله کړئ، اګر چې ما تاسو له د تکليف رسولو کوشش هم نۀ دے کړے، نو زمونږ د پلار نيکۀ خُدائ پاک به د دې نه خبر شى او تاسو له به سزا درکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10092, '1 Chronicles 12:18', '1 Chronicles', 12, 18, '&nbsp;د خُدائ پاک روح د هغوئ په يو کس عماسى باندې راغلو، چې هغه وروستو د هغه دېرشو مشر شو او هغۀ چغه ووهله، ”د يَسى زوئ داؤده، مونږ ستا يُو. کاميابى دې ستا او د هغوئ وى چې څوک ستا مدد کوى. ځکه چې خُدائ پاک ستا مل دے.“ داؤد هغوئ ته په خېر راغلے ووئيلو او په خپل لښکر يې آفسران جوړ کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10093, '1 Chronicles 12:19', '1 Chronicles', 12, 19, '&nbsp;د منسى قبيلې څۀ فوجيان واوړېدل او د داؤد په طرف شول، دا په هغه وخت کښې چې کله هغه د فلستيانو سره د ساؤل بادشاه خِلاف جنګ له روان وو. په آخر کښې هغوئ د فلستيانو مدد نۀ شو کولے، ځکه چې د هغوئ بادشاهان د دې نه يرېدل چې داؤد به د هغوئ نه خپل پخوانى نېک ساؤل ته واوړى، نو هغه يې واپس صِقلاج ته ولېږلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10094, '1 Chronicles 12:20', '1 Chronicles', 12, 20, '&nbsp;دا د منسى هغه فوجيان دى چې کله داؤد واپس صِقلاج له راتلو نو هغوئ د هغۀ په طرف شول: عدنه، يوزبد، يديعيل، ميکائيل، يوزبد، اليهُو او ضلتى. په منسى کښې د هغوئ هر يو د زرو زرو سړو فوجى قبيلې وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10095, '1 Chronicles 12:21', '1 Chronicles', 12, 21, '&nbsp;هغوئ د هغه ډلو خِلاف د داؤد ملګرتيا وکړه چې څوک ډاکوان وُو، ځکه چې هغوئ ټول تکړه جنګيالى وُو او د هغۀ د لښکر مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10096, '1 Chronicles 12:22', '1 Chronicles', 12, 22, '&nbsp;تقريباً هره ورځ به نوى سړى د داؤد سره شاملېدل، تر دې پورې چې د هغۀ لښکر د خُدائ پاک د لښکر په شان لوئ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10097, '1 Chronicles 12:38', '1 Chronicles', 12, 38, '&nbsp;دا ټول فوجيان چې د جنګ دپاره تيار وُو، حبرون ته لاړل. د هغوئ اراده دا وه چې داؤد په ټولو بنى اِسرائيلو بادشاه جوړ کړى. نو د ټولو بنى اِسرائيلو په دې خبره باندې اتفاق وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10098, '1 Chronicles 12:39', '1 Chronicles', 12, 39, '&nbsp;هغوئ هلته د داؤد سره درې ورځې تېرې کړې، د هغه مېلمستيا نه يې خوړل څښل کول چې د هغوئ خپلوانو ورله تيار کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10099, '1 Chronicles 12:40', '1 Chronicles', 12, 40, '&nbsp;د شمالى قبيلو د يساکار، زبولون او نفتالى پورې خلق د خرونو، اوښانو، قچرو او غوَيو سره راتلل چې په خوراک، اوړو، اينځرو، کشمشو، ميو او د زيتُونو تېلو باندې بار وُو. هغوئ څاروى او ګډې هم راوستل چې حلالې يې کړى او وې خورى. دا هر څۀ د هغه خوشحالۍ اظهار وو چې په ټول مُلک کښې محسوسېدله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(10100, '1 Chronicles 13:1', '1 Chronicles', 13, 1, '&nbsp;داؤد بادشاه د هغه ټولو آفسرانو سره مشوره وکړه چې زرو سړو د ډلو او د سلو سړو د ډلو مشران وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');